// Share scope: every app registers the versions it has; the runtime picks the highest one.
const scope = {}; // lib name -> list of { version, app }
function register(lib, version, app) { (scope[lib] = scope[lib] || []).push({ version, app }); }
const parse = (v) => v.split('.').map(Number);
function cmp(a, b) {
  const x = parse(a), y = parse(b);
  for (let i = 0; i < 3; i++) if (x[i] !== y[i]) return x[i] - y[i];
  return 0;
}
// Simplified caret range: same major version and at least the given version.
function satisfies(v, range) {
  const min = range.slice(1);
  return parse(v)[0] === parse(min)[0] && cmp(v, min) >= 0;
}
register('react', '18.2.0', 'shell');
register('react', '18.3.1', 'cart');
register('react', '17.0.2', 'legacy');
// Singleton: one copy for everybody, the highest registered version.
const chosen = scope.react.map((e) => e.version).sort(cmp).pop();
console.log('registered:', scope.react.map((e) => e.app + '@' + e.version).join(', '));
console.log('singleton chosen:', chosen);
const consumers = { shell: '^18.2.0', cart: '^18.3.0', legacy: '^17.0.0' };
for (const app of Object.keys(consumers)) {
  const ok = satisfies(chosen, consumers[app]);
  console.log(app + ' wants ' + consumers[app] + ' -> ' + (ok ? 'ok' : 'WARNING: version mismatch'));
}

// Two copies of React: hooks only work with the copy that has an active renderer.
function makeReact(name) {
  let dispatcher = null; // set by the renderer that belongs to THIS copy
  return {
    name,
    setDispatcher(d) { dispatcher = d; },
    useState(initial) {
      if (!dispatcher) throw new Error('Invalid hook call: ' + name + ' has no active renderer');
      return dispatcher.useState(initial);
    },
  };
}
// The host's react-dom renders with the host's React copy.
function render(react, component) {
  react.setDispatcher({ useState: (v) => [v, () => {}] });
  try { return component(); } finally { react.setDispatcher(null); }
}
