// Three token layers: primitive -> semantic (per theme) -> component.
const primitive = { 'blue.600': '#2563eb', 'blue.400': '#60a5fa', white: '#ffffff', 'gray.900': '#111827' };
const semantic = {
  light: { 'color.action': '{blue.600}', 'color.bg': '{white}' },
  dark: { 'color.action': '{blue.400}', 'color.bg': '{gray.900}' },
};
const component = { 'button.bg': '{color.action}', 'button.text': '{color.bg}' };
// Follow {references} until a raw value is reached.
function resolve(ref, theme) {
  const name = ref.replace(/[{}]/g, '');
  const next = component[name] || semantic[theme][name] || primitive[name];
  return next.startsWith('{') ? resolve(next, theme) : next;
}
function luminance(hex) {
  const c = [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16) / 255)
    .map((v) => (v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4)));
  return 0.2126 * c[0] + 0.7152 * c[1] + 0.0722 * c[2];
}
function contrast(a, b) {
  const [hi, lo] = [luminance(a), luminance(b)].sort((x, y) => y - x);
  return (hi + 0.05) / (lo + 0.05);
}
for (const theme of ['light', 'dark']) {
  const bg = resolve('{button.bg}', theme), text = resolve('{button.text}', theme);
  const ratio = contrast(bg, text);
  // CI gate: fail the build if body-size text is below 4.5:1
  console.log(theme + ': button.bg=' + bg + ' button.text=' + text + ' contrast=' + ratio.toFixed(2) + (ratio >= 4.5 ? ' PASS' : ' FAIL'));
}

// Affected detection and a content-hash task cache (what Nx/Turborepo do, in miniature).
const crypto = require('crypto');
const pkgs = {
  utils: { deps: [], src: 'v1' },
  ui: { deps: ['utils'], src: 'v1' },
  app: { deps: ['ui'], src: 'v1' },
  docs: { deps: ['ui'], src: 'v1' },
};
const env = { API_URL: 'https://staging.example.test' };
const cache = new Set();
const sha = (s) => crypto.createHash('sha1').update(s).digest('hex').slice(0, 8);
// A task hash covers its own source plus the hashes of everything it depends on.
function hashOf(name, envKeys) {
  const p = pkgs[name];
  return sha(name + p.src + p.deps.map((d) => hashOf(d, envKeys)).join('') + envKeys.map((k) => env[k]).join(''));
}
function affected(changed) {
  const set = new Set(changed);
  let grew = true;
  while (grew) {
    grew = false;
    for (const n of Object.keys(pkgs))
      if (!set.has(n) && pkgs[n].deps.some((d) => set.has(d))) { set.add(n); grew = true; }
  }
  return [...set];
}
function build(label, envKeys) {
  const out = Object.keys(pkgs).map((n) => {
    const h = hashOf(n, envKeys);
    const hit = cache.has(h); cache.add(h);
    return n + ':' + (hit ? 'HIT' : 'MISS');
  });
  console.log(label.padEnd(30) + out.join(' '));
}
build('first run', ['API_URL']);
build('nothing changed', ['API_URL']);
pkgs.app.src = 'v2';
build('edit app only', ['API_URL']);
console.log('affected by utils edit:', affected(['utils']).join(', '));
pkgs.utils.src = 'v2';
build('edit utils', ['API_URL']);
build('key without env (warm)', []);
env.API_URL = 'https://prod.example.test';
build('API_URL changed, in key', ['API_URL']);
build('API_URL changed, NOT in key', []); // HITs replay the staging build for prod

// Three caching strategies against a fake network and cache.
const cache = new Map();
let serverVersion = 1, online = true;
const network = (url, delay) => new Promise((res, rej) =>
  setTimeout(() => (online ? res(url + '@v' + serverVersion) : rej(new Error('offline'))), delay || 0));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function cacheFirst(url) {            // hashed assets
  if (cache.has(url)) return cache.get(url) + ' [cache]';
  const r = await network(url); cache.set(url, r); return r + ' [network]';
}
async function networkFirst(url, timeoutMs) { // HTML
  const timer = new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), timeoutMs));
  try {
    const r = await Promise.race([network(url, 30), timer]);
    cache.set(url, r); return r + ' [network]';
  } catch (e) {
    return (cache.get(url) || 'offline-page') + ' [fallback: ' + e.message + ']';
  }
}
async function staleWhileRevalidate(url) {    // read-only API data
  const stale = cache.get(url);
  const fresh = network(url).then((r) => { cache.set(url, r); return r; });
  fresh.catch(() => {});                        // ignore background failures
  return stale ? stale + ' [stale, refreshing]' : (await fresh) + ' [network]';
}
(async () => {
  console.log('cache-first      ', await cacheFirst('/app.3f2a.js'));
  console.log('cache-first      ', await cacheFirst('/app.3f2a.js'));
  console.log('network-first    ', await networkFirst('/home', 100));
  serverVersion = 2;
  console.log('network-first    ', await networkFirst('/home', 10)); // slow network
  console.log('swr              ', await staleWhileRevalidate('/api/feed'));
  serverVersion = 3; await sleep(5);
  console.log('swr              ', await staleWhileRevalidate('/api/feed'));
  await sleep(5);
  console.log('swr (next visit) ', await staleWhileRevalidate('/api/feed'));
  online = false;
  console.log('offline html     ', await networkFirst('/home', 100));
})();

// Outbox: local write + queued message, flushed oldest-first, retried, deduplicated by id.
const notes = {};                 // local database (source of truth for the UI)
const outbox = [];                // messages waiting for the server
const serverNotes = {}, seen = new Set(), tries = {};
function saveLocally(id, text) {  // in real code both writes share one IndexedDB transaction
  notes[id] = text;
  outbox.push({ id: 'msg-' + outbox.length, op: 'put', payload: { id, text } });
}
function serverApply(msg) {
  tries[msg.id] = (tries[msg.id] || 0) + 1;
  if (msg.id === 'msg-1' && tries[msg.id] < 2) throw { transient: true };   // first try fails
  if (msg.op === 'bad') throw { transient: false };                         // permanent 4xx
  if (seen.has(msg.id)) return 'duplicate ignored';                          // idempotency key
  seen.add(msg.id); serverNotes[msg.payload.id] = msg.payload.text; return 'applied';
}
function flush() {
  const dead = [];
  while (outbox.length) {
    const msg = outbox[0];
    try {
      console.log(msg.id + ' -> ' + serverApply(msg));
      outbox.shift();                                // delete only after the server confirmed
    } catch (e) {
      if (!e.transient) { console.log(msg.id + ' permanent failure -> dead letter'); dead.push(outbox.shift()); continue; }
      const wait = 500 * 2 ** (tries[msg.id] - 1);  // exponential backoff (jitter omitted)
      console.log(msg.id + ' transient failure, retry after ' + wait + 'ms');
    }
  }
  return dead;
}
saveLocally('n1', 'buy milk');
saveLocally('n2', 'call bank');
outbox.push({ id: 'msg-9', op: 'bad', payload: { id: 'n3', text: 'x' } });
const resend = outbox[0];
const dead = flush();
console.log('lost ack, client resends msg-0 -> ' + serverApply(resend));
console.log('server:', JSON.stringify(serverNotes), 'dead letters:', dead.length);

