    // Stable percentage rollout: bucket = FNV-1a(flag:user) % 100; enabled when bucket < percent.
    static long fnv1a(String text) {
        int h = (int) 2166136261L;                 // FNV offset basis (32-bit)
        for (byte b : text.getBytes()) {
            h ^= (b & 0xFF);                       // mix in one byte
            h *= 16777619;                         // int overflow keeps 32 bits
        }
        return h & 0xFFFFFFFFL;                    // treat as unsigned
    }
    static int bucket(String flag, String user) { return (int) (fnv1a(flag + ":" + user) % 100); }
    static boolean enabled(String flag, String user, int percent) { return bucket(flag, user) < percent; }

