using System;
using System.Text;

class Program
{
    // Stable percentage rollout: bucket = FNV-1a(flag:user) % 100; enabled when bucket < percent.
    static uint Fnv1a(string text)
    {
        uint h = 2166136261u;                    // FNV offset basis (32-bit)
        foreach (byte b in Encoding.UTF8.GetBytes(text))
        {
            h ^= b;                              // mix in one byte
            h = unchecked(h * 16777619u);        // wrap at 32 bits
        }
        return h;
    }
    static int Bucket(string flag, string user) { return (int)(Fnv1a(flag + ":" + user) % 100); }
    static bool Enabled(string flag, string user, int percent) { return Bucket(flag, user) < percent; }

    static void Main()
    {
        for (int i = 1; i <= 5; i++)
        {
            string u = "user-" + i;
            Console.WriteLine(u + " checkout-v2 -> bucket " + Bucket("checkout-v2", u)
